/** Save focused readable examples generated by the real native prover. */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pedalFixture } from '../src/features/geogebra/reasoning/__fixtures__/pedal';
import { exportAg2Queries } from '../src/features/geogebra/reasoning/backends/ag2/exportProblem';
import type { Ag2RunResult } from '../src/features/geogebra/reasoning/backends/ag2/protocol';
import { focusProof, proofToMarkdown } from '../src/features/geogebra/reasoning/proof/formatProof';

const source = `import sys
sys.dont_write_bytecode = True
sys.path[:0] = ['public/geometry-reasoning', 'public/vendor/alphageometry2']
from ag2_bridge import solve_json
print(solve_json(sys.stdin.read()))
`;
for (const [center, goal, filename] of [
  ['orthocenter', 'nine-point', 'orthocenter-nine-point'],
  ['incenter', 'contact-polar', 'incenter-contact-polar'],
] as const) {
  const fixture = pedalFixture(center, 0, true);
  const exported = exportAg2Queries(fixture.problem, fixture.acceptedIds, [goal]).value!;
  exported.operation = 'proof';
  exported.names = exported.names.map((entry) => entry.name === 'X' ? { ...entry, name: center === 'incenter' ? 'I' : 'H' } : entry);
  const result = JSON.parse(execFileSync('python', ['-c', source], { input: JSON.stringify(exported), encoding: 'utf8' })) as Ag2RunResult;
  if (!result.proof?.algebraReplay.valid || result.proof.gapIds.length || result.proof.limited
    || result.proof.conclusions.some((entry) => entry.status !== 'recorded')) throw new Error('Incomplete pedal example');
  const proof = focusProof(result.proof, result.proof.conclusions[0].nodeId);
  const directory = resolve('src/features/geogebra/reasoning/docs/examples');
  writeFileSync(resolve(directory, `${filename}.md`), proofToMarkdown(proof, exported), 'utf8');
  writeFileSync(resolve(directory, `${filename}.json`), JSON.stringify({ input: exported, result }, null, 2), 'utf8');
  process.stdout.write(`${filename}: ${proof.nodes.length} focused steps, ${proof.algebraReplay.checked} algebra steps, ${proof.guardIds.length} guards.\n`);
}
